from pathlib import Path
from PIL import Image,ImageOps,ImageDraw
import json,hashlib,html
root=Path(__file__).resolve().parents[1];out=root/'revisions/v17';v=out/'verification'
def registry(p):return json.loads(p.read_text(encoding='utf8').split('window.KonohaScenes=')[1].strip().rstrip(';'))
before=registry(out/'before/prototype/scenes.js');after=registry(root/'prototype/scenes.js');parts=[]
for id in ['night','rocklee','sai']:
 a=next(s for s in before if s['id']==id);b=next(s for s in after if s['id']==id)
 parts.append('<section><h2>'+html.escape(b['name'])+'</h2><div class="pair">'+''.join('<figure><figcaption>'+label+'</figcaption><a href="../../../assets/runtime/'+s['image']+'"><img src="../../../assets/runtime/'+s['image']+'" alt="'+html.escape(s['name']+' '+label)+'"></a></figure>' for label,s in [('v16',a),('v17',b)])+'</div><details><summary>У макеті: TV / компактний / вузький екран</summary><div class="screens">'+''.join('<a href="'+id+'-'+str(w)+'.png"><img src="'+id+'-'+str(w)+'.png" alt="'+html.escape(b['name'])+' '+str(w)+'"></a>' for w in [1920,960,390])+'</div></details></section>')
page='''<!doctype html><html lang="uk"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Konoha v17 — порівняння</title><style>body{margin:0;background:#0b202b;color:#ead9b4;font:16px system-ui;line-height:1.6}main{max-width:1500px;margin:auto;padding:32px}h1,h2{line-height:1.2}h1{font-size:40px}h2{margin-top:0}p{max-width:950px;color:#b8c8c5}a{color:#f4b969}section{margin:32px 0;padding:24px;border:1px solid #b9976544;background:#102b38;border-radius:8px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}figure{margin:0}figcaption{color:#d4bc94;margin-bottom:8px}img{display:block;width:100%;height:auto}.screens{display:flex;align-items:start;gap:12px;margin-top:16px}.screens a{width:40%}.screens a:last-child{width:20%}summary{cursor:pointer;padding-top:16px}.manager img{max-width:900px}button{font:inherit}@media(max-width:650px){main{padding:16px}.pair{grid-template-columns:1fr}section{padding:12px}h1{font-size:30px}}</style><main><h1>Konoha · v17</h1><p>Порядок обраних застосунків, чистіший головний екран і три нові сцени у стилі TV anime cel. Натисни малюнок для оригінального runtime-файла. Доопрацювання створено built-in ImageGen зі скілом anime-tv-cel-art; попередні ресурси збережені.</p><p><a href="../../../prototype/">Відкрити інтерактивний лаунчер</a> · <a href="../REPORT.md">Звіт</a> · <a href="../generation-manifest.json">Промпти</a> · <a href="../references/sources.json">Референси</a></p><section class="manager"><h2>Порядок обраного</h2><p>Весь архів → Порядок обраного. Обрати ↑ або ↓ біля застосунку → OK. Перші шість позицій показуються на головному екрані. Навігаційні стрілки змінюють фокус, а порядок зберігається після OK.</p><a href="order-1920.png"><img src="order-1920.png" alt="Менеджер порядку застосунків"></a></section>'''+''.join(parts)+'''<p>Перевірено у Chromium на 1920×1080, 960×540, 390×844. Вузький екран кадрує широкі сцени; усю взаємодію клонів і чорнильного тигра видно у TV-композиції. Фізичний TV, пульт і Android WebView не перевірялися.</p></main></html>'''
(v/'visual-review.html').write_text(page,encoding='utf8')
sheet=Image.new('RGB',(1440,1220),'#102b38');d=ImageDraw.Draw(sheet)
for i,id in enumerate(['night','rocklee','sai']):
 sheet.paste(ImageOps.contain(Image.open(v/f'{id}-960.png'),(480,280)),(i*480,24));d.text((i*480+12,6),id,fill='white');sheet.paste(Image.open(v/f'{id}-390.png'),(i*480+40,340))
sheet.save(v/'contact-sheet.jpg',quality=93)
hashes={p.relative_to(root).as_posix():hashlib.sha256(p.read_bytes()).hexdigest() for p in (root/'prototype').rglob('*') if p.is_file()};(v/'source-hashes.json').write_text(json.dumps(hashes,indent=2),encoding='utf8');print('v17 comparison gallery and product hashes written')
